/* Visual storytelling layer. Brand expression is separate from product usage. */
const originalPages={...pages};
const pointer=(name='Alex',kind='arrow')=>`<span class="collab-pointer pointer-${kind}" aria-hidden="true">${kind==='pen'?'<svg viewBox="0 0 32 32"><path d="m7 23 1-7L23 1l8 8-15 15-8 1Z M19 5l8 8 M8 16l8 8 M3 29l5-4"/></svg>':icon('cursor')}<span>${name}</span></span>`;
const pageTop=(name,modifier,art)=>`<section class="express-hero ${modifier}"><div class="express-meta"><a href="#/direction">All directions</a><span>DesignOS / ${name}</span><span>Scroll to explore</span></div>${art}<h1>${name}<span>.</span></h1><span class="hero-bottom-note">A living creative language</span></section>`;
const statementScene=(text,kind='')=>`<section class="scroll-scene word-scene ${kind}" data-scene="words"><div class="scene-sticky"><p class="scroll-statement" aria-label="${text}">${text.split(' ').map((w,i)=>`<span class="reveal-word" style="--word:${i}" aria-hidden="true">${w} </span>`).join('')}</p><div class="scene-caption"><span>Expression in motion</span><span class="scroll-meter" aria-hidden="true"><i></i></span></div></div></section>`;
function usage(title,summary,items){return `<section class="usage-section"><div><span class="eyebrow">In the product</span><h2>${title}</h2><p>${summary}</p></div><div class="usage-details">${items.map(([name,content])=>`<details><summary>${name}<span aria-hidden="true">+</span></summary><div class="usage-content">${content}</div></details>`).join('')}</div></section>`}
const skinSets=[['Teal on mint','#c2f4d7','#006b60','#172724'],['Mint on ink','#172724','#c2f4d7','#f8f9f6'],['Ink on canvas','#f8f9f6','#172724','#172724'],['Canvas on teal','#006b60','#f8f9f6','#f8f9f6']];
function paletteRail(){return `<div class="palette-rail" role="group" aria-label="Choose composition colors">${skinSets.map(([n,bg,fg],i)=>`<button class="rail-swatch ${i===0?'selected':''}" data-skin="${i}" style="--swatch-bg:${bg};--swatch-fg:${fg}" aria-label="${n}" aria-pressed="${i===0}"><i></i></button>`).join('')}<span>Try a pairing</span></div>`}
function colorPlay(){return `<section class="color-play" data-scene="color-play" style="--play-bg:#c2f4d7;--play-fg:#006b60;--play-ink:#172724"><div class="play-heading"><span class="meta">A palette in practice</span><h2>A change of color.<br>A new perspective.</h2></div><div class="color-theater">${paletteRail()}<div class="art-poster"><span class="poster-brand">DesignOS</span><h3>Make<br>something<br><em>unexpected.</em></h3><div class="poster-sculpture" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><span class="poster-bottom">A little structure. Endless possibility.</span>${pointer('Maya','pen')}</div><div class="floating-invite"><span class="meta">Your next idea</span><strong>Starts<br>right here.</strong><span>DesignOS / Creative workspace</span></div><div class="floating-ui"><span class="meta">Product example</span><h4>Brand exploration</h4><p>A clear canvas for your next direction.</p><div class="ui-swatches"><i></i><i></i><i></i></div><button class="product-action demo-create-skin">Create project</button></div></div><span class="play-note">Brand compositions can be expressive. Product surfaces stay focused.</span></section>`}
function colorExperience(){return pageTop('Color','hero-color',`<div class="color-ribbons" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="hero-tool">${pointer('Maya','pen')}</div>`)+statementScene('A quiet foundation. A bold point of view. Color gives every idea a place to begin.','color-words')+`<section class="scroll-scene palette-scene" data-scene="palette"><div class="scene-sticky"><div class="scene-topline"><span class="meta">The core palette</span><span class="meta">Click a layer to copy</span></div><div class="fan-palette">${palette.map(([n,h],i)=>`<button class="fan-layer" style="--layer:${i};--layer-color:${h};--layer-ink:${i===1||i===2?'#f8f9f6':'#172724'}" data-copy="${h}" aria-label="Copy ${n} ${h}"><span>${n}</span><strong>${h}</strong><i aria-hidden="true">${i===0?'A clear canvas.':i===1?'Room to focus.':i===2?'A little intention.':i===3?'Open to possibility.':'Space to create.'}</i></button>`).join('')}</div><div class="scene-caption"><span>Five colors. A world of combinations.</span><span>Scroll to unfold</span></div></div></section>`+colorPlay()+usage('Color that does a job.','Keep the dashboard mostly neutral. Let color guide the next action.',[['Core colors & accessible pairs',`<div class="usage-swatches">${palette.map(([n,h])=>`<button data-copy="${h}" style="--c:${h}"><i></i>${n}<code>${h}</code></button>`).join('')}</div><p>Ink on Canvas: ${ratio('#172724','#F8F9F6')}:1. White on Teal: ${ratio('#FFFFFF','#006B60')}:1. Ink on Mint: ${ratio('#172724','#C2F4D7')}:1. Each passes AA normal-text contrast.</p>`],['Light & dark roles','<p>Light: Canvas #F8F9F6, White surfaces, Ink text, Deep teal actions. Dark: #121B19 background, #1C2824 surfaces, #F3F6F1 text, #9DE4C3 actions with Ink labels. Decorative dividers never replace a visible control boundary.</p>'],['Usage, status & gradients','<p>Mint is an expressive background with Ink text. Use success, warning, error and info colors with labels or icons. Tonal gradients belong to artwork; text and controls sit on solid surfaces.</p><a class="text-link" href="assets/tokens.json" download>Download exact tokens</a>']])+next('color')}
function typeExperience(){return pageTop('Typography','hero-typography',`<div class="type-orbit" aria-hidden="true"><span>Aa</span><span>Bold.</span><span>Regular</span><span>Medium</span></div>${pointer('Alex')}`)+`<section class="scroll-scene weight-scene" data-scene="type"><div class="scene-sticky"><div class="scene-topline"><span class="meta">Manrope / a range of expression</span><span class="live-weight meta">400 / Regular</span></div><div class="weight-word" aria-label="Make it yours.">Make it<br><em>yours.</em></div><div class="weight-scale" aria-hidden="true"><span>400</span><i></i><span>800</span></div><div class="scene-caption"><span>A voice you can see.</span><span>Scroll through the weights</span></div></div></section>`+`<section class="type-composition" data-parallax><span class="meta">Hierarchy, in real life</span><div class="type-line type-line-display">Big ideas.</div><div class="type-line type-line-bold">Clear decisions.</div><div class="type-line type-line-medium">A place to bring them together.</div><div class="type-line type-line-body">The headline leads. The subheading explains.<br>The body gives you somewhere to go next.</div><div class="type-composition-labels"><span>Manrope 800 · Display</span><span>Manrope 700 · Heading</span><span>DM Sans 500 · Subheading</span><span>DM Sans 400 · Body</span></div>${pointer('Alex')}</section>`+`<section class="type-product-scene"><div class="type-product-heading"><span class="meta">Built for a workspace</span><h2>Expressive up here.<br>Useful down here.</h2></div><div class="type-product-window"><div class="window-bar"><span></span><span></span><span></span></div><div class="type-ui-content"><span class="meta">Your workspace</span><h3>Good things take shape.</h3><p>A place for your designs, images and brand explorations.</p><div class="type-ui-row"><strong>Recent projects</strong><span>View all</span></div><div class="type-ui-project"><div class="type-ui-thumbnail">Aa</div><div><h4>A new perspective</h4><p>Brand exploration · Edited today</p></div><span class="type-ui-tag">Draft</span></div></div></div></section>`+section('Try a few words.','Change the text, size and weight.',`<div class="visual-stage"><div class="controls"><label>Your words <input id="type-input" type="text" value="Make room for ideas." maxlength="100"></label><label>Size <input id="type-size" type="range" min="28" max="130" value="80"><output id="type-size-label">80 px</output></label><label>Weight <select id="type-weight"><option value="400">Regular 400</option><option value="500">Medium 500</option><option value="700" selected>Bold 700</option><option value="800">Extra bold 800</option></select></label></div><div class="specimen" id="specimen" style="font-size:80px;font-weight:700">Make room for ideas.</div></div>`)+usage('Hierarchy before decoration.','A strong heading, a clear subheading and comfortable reading text.',[['Families & roles','<p>Manrope 600–800 for display and product headings. DM Sans 400 for body; 500–600 for labels and supporting headings. IBM Plex Mono 400–500 for code and secondary metadata. Fonts use the SIL Open Font License, with Arial/sans-serif and monospace fallbacks.</p>'],['Product scale','<p>Display 64/68 or fluid on brand pages. Page title 32/38 at 700. Section heading 24/30 at 700. Subheading 18/26 at 600. Body 16/24 at 400. Controls 14/20 at 500. Metadata 12/18 only. Preserve a clear weight difference between headings and body.</p>'],['Readable in both modes','<p>Use the semantic text tokens, not low-opacity white or gray. Keep long copy at a comfortable measure. Tight tracking belongs to large headlines; normal tracking belongs to the dashboard.</p>']])+next('typography')}
function imageryExperience(){return pageTop('Imagery','hero-imagery',`<div class="image-planet" aria-hidden="true"><img src="assets/orbit.svg" alt=""></div><div class="image-frame frame-one" aria-hidden="true"></div><div class="image-frame frame-two" aria-hidden="true"></div>${pointer('Noor','pen')}`)+`<section class="scroll-scene sculpture-scene" data-scene="sculpture"><div class="scene-sticky"><div class="scene-topline"><span class="meta">One visual language</span><span class="meta">Different dimensions</span></div><div class="sculpture-world"><div class="sculpture-orbit"><img src="assets/orbit.svg" alt="Tonal orbital artwork"></div><div class="sculpture-flat"></div><div class="sculpture-wire"><i></i><i></i><i></i><i></i></div><h2>Give an idea<br><em>some shape.</em></h2>${pointer('Noor')}</div><div class="scene-caption"><span>From a sketch to a new perspective.</span><span>Scroll to compose</span></div></div></section>`+`<section class="imagery-gallery"><div class="gallery-art art-large"><img src="assets/orbit.svg" alt="Dimensional tonal teal orbital form"><span>Dimension / tonal, tactile, focused</span></div><div class="gallery-art art-outline"><div class="wire-shape" aria-hidden="true">${'<i></i>'.repeat(9)}</div><span>Outline / the shape of a thought</span></div><div class="gallery-caption"><h2>Same idea.<br>New dimension.</h2><p>A restrained set of materials, shapes and colors.<br>Enough room for a lot of expression.</p></div><div class="gallery-art art-flat"><div class="flat-bloom" aria-hidden="true">${'<i></i>'.repeat(6)}</div><span>Flat / clear by nature</span></div></section>`+usage('A recognizable point of view.','The artwork is expressive. Product imagery tells a real story.',[['Forms, light & palette','<p>Rounded forms, layered planes, matte material and one directional light. Keep dimensional imagery tonal: teal, mint and neutral surfaces. A single clear subject and generous negative space.</p>'],['Photography & product captures','<p>Show real making and reviewing, with natural directional light and honest color. Product images use realistic workflows; label illustrative concepts. Avoid unrelated AI planets, robot brains and stock-photo filler.</p>'],['Original asset','<p>The orbital artwork is a graphic device, not the final logo.</p><a class="text-link" href="assets/orbit.svg" download>Download SVG artwork</a>']])+next('imagery')}
function iconExperience(){const names=['folder','image','layers','cursor','type','globe','spark','handoff'];return pageTop('Iconography','hero-iconography',`<div class="hero-icon-cloud" aria-hidden="true">${names.map((n,i)=>`<span style="--i:${i}">${icon(n)}</span>`).join('')}</div>${pointer('Maya')}`)+`<section class="scroll-scene icon-magnet-scene" data-scene="icons"><div class="scene-sticky"><div class="scene-topline"><span class="meta">One stroke language</span><span class="meta">24 px / 1.75 px</span></div><h2>Small things.<br><em>Instant meaning.</em></h2><div class="magnet-icons" aria-hidden="true">${names.map((n,i)=>`<span style="--i:${i}">${icon(n)}</span>`).join('')}</div><div class="scene-caption"><span>Scattered possibilities. A familiar vocabulary.</span><span>Scroll to align</span></div></div></section>`+section('A useful little collection.','Search, then select an icon to download its SVG.',`<label class="controls">Find an icon <input class="search" id="icon-search" placeholder="Try folder, image, layers…" type="search"></label><div class="icon-grid">${iconNames.map(n=>`<button class="icon-cell" data-icon="${n}" aria-label="Download ${n} icon">${icon(n)}<span>${n}</span></button>`).join('')}</div><p class="empty-result" hidden>No matching icons. Try “folder” or “image”.</p>`)+usage('Clarity at every size.','The familiar action matters more than the decorative detail.',[['Construction','<p>24 px base grid. 1.75 px stroke. Round caps and joins. Use 16, 20 and 24 px output sizes with optical checks. Avoid mixing filled and outline icon families within the same control group.</p>'],['Meaning & accessibility','<p>Use the same semantic text token as surrounding controls. Pair unfamiliar actions with text. Every icon-only control needs an accessible name and a visible focus state.</p>']])+next('iconography')}
function motionExperience(){return pageTop('Motion','hero-motion',`<div class="hero-motion-shapes" aria-hidden="true"><i></i><i></i><i></i></div>${pointer('Alex')}`)+`<section class="scroll-scene workflow-scene" data-scene="workflow"><div class="scene-sticky"><div class="scene-topline"><span class="meta">Our signature gesture</span><span class="meta">Possibility becomes a place</span></div><div class="motion-canvas"><div class="motion-artifact artifact-prompt"><span class="meta">The starting point</span><strong>A thought.</strong><p>Make something that feels like me.</p></div><div class="motion-artifact artifact-image"><img src="assets/orbit.svg" alt="Generated artwork example"><span>A new perspective.</span></div><div class="motion-artifact artifact-result"><span class="meta">The next direction</span><strong>A thing.</strong><div class="result-swatch"></div><span>Ready to make your own.</span></div>${pointer('Alex')}</div><div class="scene-caption"><span>Nothing appears without somewhere to come from.</span><span>Scroll to bring it together</span></div></div></section>`+`<section class="motion-playground"><div class="play-heading"><span class="meta">Feel the difference</span><h2>A rhythm for the moment.</h2></div><div class="motion-play-controls" role="group" aria-label="Motion timing"><button class="active" aria-pressed="true" data-timing="180">Feedback <span>180 ms</span></button><button aria-pressed="false" data-timing="280">Transition <span>280 ms</span></button><button aria-pressed="false" data-timing="800">Expression <span>800 ms</span></button><button id="replay-composition" aria-label="Replay composition">Replay</button></div><div class="replay-composition" aria-label="Three creative fragments assembling into a composition"><div>Think.</div><div>Make.</div><div>Shape.</div>${pointer('Maya')}</div><p class="motion-play-label">cubic-bezier(0.22, 1, 0.36, 1)</p></section>`+usage('Movement with a purpose.','The brand can travel further. The dashboard responds quickly.',[['Timing & easing','<p>180 ms feedback, 280 ms transitions and 800 ms expressive sequences. Ease: cubic-bezier(0.22,1,0.36,1). Product motion should explain a state change without delaying work.</p>'],['Control & reduced motion','<p>Natural scrolling, no scroll hijacking. Respect prefers-reduced-motion: remove travel, continuous drift and parallax; show the complete composition. The “Reduce motion” control on these pages offers the same option.</p>'],['Loading is a real state','<p>Use honest generation status, cancellation when supported and recoverable errors. Decorative motion never implies completion or invents progress percentages.</p>']])+next('motion')}
function voiceExperience(){return pageTop('Voice & tone','hero-voice',`<div class="voice-notes" aria-hidden="true"><span>A little<br>more you.</span><span>Let’s see<br>where it goes.</span><span>Your idea.<br>Your next step.</span></div>${pointer('Noor')}`)+statementScene('A thoughtful partner. A little encouragement. The right words at the right moment.','voice-words')+`<section class="voice-play"><span class="meta">Same personality. Different moments.</span><div class="voice-tabs" role="group" aria-label="Example message"><button class="active" aria-pressed="true" data-voice="start">Starting</button><button aria-pressed="false" data-voice="success">Success</button><button aria-pressed="false" data-voice="error">Something went wrong</button></div><div class="voice-message"><span class="message-icon">${icon('folder')}</span><h2>A little space<br>for your next idea.</h2><p>Create a project to get started.</p><span class="voice-action">Create project</span>${pointer('Alex')}</div></section>`+usage('Say the useful thing.','Clear, encouraging and honest. A partner in the process.',[['Be specific','<p>Use short sentences and concrete actions. “Create project”, “Export image”, “Review your brand kit”. Let the work provide the excitement.</p>'],['Adapt to the moment','<p>Starting: encouraging and open. Success: calm and specific. Errors: direct, considerate and actionable. Avoid forced humor when someone needs help.</p>'],['Tell the truth','<p>Describe drafts as drafts. Explain limitations. Never claim the user’s work is finished, approved or saved unless that is actually true.</p>']])+next('voice')}
function formExperience(){return pageTop('Form & detail','hero-form',`<div class="form-hero-shapes" aria-hidden="true"><i></i><i></i><i></i></div>${pointer('Maya','pen')}`)+`<section class="scroll-scene form-scene" data-scene="form"><div class="scene-sticky"><div class="scene-topline"><span class="meta">A shape for every job</span><span class="meta">6 / 10 / 16</span></div><div class="form-blocks"><div><span>6 px</span><strong>Precise<br>controls.</strong></div><div><span>10 px</span><strong>Useful<br>containers.</strong></div><div><span>16 px</span><strong>Room to<br>express.</strong></div></div><div class="scene-caption"><span>Consistency underneath. Possibility on the surface.</span><span>Scroll to shape</span></div></div></section>`+`<section class="detail-composition"><div class="detail-type"><span class="meta">Details make the difference</span><h2>Less chrome.<br>More clarity.</h2></div><div class="detail-spec"><div class="detail-demo-field"><label>Project name</label><div>A new perspective<span>⌘ K</span></div></div><div class="detail-demo-actions"><button class="product-action" id="focus-example">Create project</button><span>6 px radius · clear affordance</span></div><div class="detail-stroke"><i></i><span>1 px dividers</span><i></i><span>1.75 px icons</span></div></div></section>`+usage('Quiet decisions. Better work.','Give each surface and control a clear role.',[['Radius & space','<p>6 px controls, 10 px product cards, 16 px brand panels. Full rounding is reserved for chips and compact toggles. Spacing follows a 4 px base: 4, 8, 12, 16, 24, 32, 48 and 64.</p>'],['Strokes & focus','<p>1 px decorative dividers. 1.75 px icons at 24 px. 3 px focus outline on this site. Essential control boundaries need 3:1 contrast; decorative dividers may be quieter.</p>'],['Product hierarchy','<p>Use stable alignment, proximity and a single dominant action. Reading text is at least 16 px; labels and controls default to 14 px. Strong headings distinguish structure from detail.</p>']])+next('foundations')}
function applicationsExperience(){return pageTop('In practice','hero-applications',`<div class="applications-hero-collage" aria-hidden="true"><div>From a thought.<br>To a thing.</div><img src="assets/presentation.svg" alt=""><img src="assets/product-concept.svg" alt=""></div>${pointer('Alex')}`)+statementScene('One identity. A thousand starting points. Always recognizable. Always room for you.','application-words')+`<section class="application-stage"><div class="application-label"><span class="meta">Everyday clarity</span><h2>A workspace<br>for the work.</h2></div>${productDemo()}</section>`+colorPlay()+usage('A system that travels.','Test the identity where people actually experience it.',[['Dashboard','<p>Neutral surfaces, one clear primary action, bold headings and restrained accents. Use the light/dark token set. Brand artwork never competes with the task.</p>'],['Launch & presentation','<p>Use oversized Manrope, purposeful crops, layered tonal imagery and more expressive motion. Keep text contrast high even when the composition is playful.</p>'],['Reusable assets','<a class="text-link" href="#/resources">Get the SVG applications and brand tokens</a>']])+next('applications')}
function newHome(){let html=originalPages.home();html=html.replace('<div class="hero-top">','<div class="home-collab-layer" aria-hidden="true">'+pointer('Alex')+pointer('Maya','pen')+pointer('Noor')+'</div><div class="hero-top">');html=html.replace('<div class="piece piece-ui">','<div class="piece piece-ui"><span class="selection-corners" aria-hidden="true"><i></i><i></i><i></i><i></i></span>');return html}
pages.home=newHome;pages.color=colorExperience;pages.typography=typeExperience;pages.imagery=imageryExperience;pages.iconography=iconExperience;pages.motion=motionExperience;pages.voice=voiceExperience;pages.foundations=formExperience;pages.applications=applicationsExperience;
let disposeExperience=()=>{};
const previousBind=bind;
bind=function(){previousBind();disposeExperience();const root=$('#main');const sceneNodes=$$('[data-scene]',root);const reducedQuery=matchMedia('(prefers-reduced-motion: reduce)');let userReduced=false;try{userReduced=localStorage.getItem('brand-reduced')==='true'}catch(e){}
if($('.express-hero')){const control=document.createElement('button');control.className='motion-access';control.textContent='Reduce motion';control.setAttribute('aria-pressed',userReduced||reducedQuery.matches);control.onclick=()=>{userReduced=!userReduced;try{localStorage.setItem('brand-reduced',String(userReduced))}catch(e){}updateReduced();updateScenes()};$('.express-meta').append(control)}
const updateReduced=()=>{const off=userReduced||reducedQuery.matches;root.classList.toggle('motion-reduced',off);$('.motion-access')?.setAttribute('aria-pressed',off);if($('.motion-access'))$('.motion-access').textContent=off?'Motion reduced':'Reduce motion'};updateReduced();
let ticking=false;function updateScenes(){ticking=false;const reduced=userReduced||reducedQuery.matches;const vh=innerHeight;sceneNodes.forEach(scene=>{const r=scene.getBoundingClientRect();if(r.bottom < -vh || r.top>vh*2)return;let p=reduced?.65:Math.max(0,Math.min(1,-r.top/Math.max(1,scene.offsetHeight-vh)));scene.style.setProperty('--p',p.toFixed(4));const st=$('.scene-sticky',scene);if(scene.dataset.scene==='color-play'){const q=reduced?.5:Math.max(0,Math.min(1,(vh-r.top)/(vh+scene.offsetHeight)));$('.art-poster',scene).style.transform=`translateY(${(q-.5)*-70}px) rotate(${-6+(q-.5)*5}deg)`;$('.floating-ui',scene).style.transform=`translateY(${(q-.5)*90}px) rotate(5deg)`;$('.floating-invite',scene).style.transform=`translateY(${(q-.5)*-40}px) rotate(8deg)`}if(scene.dataset.scene==='words'){const sets=[['#172724','#c2f4d7'],['#006b60','#f8f9f6'],['#c2f4d7','#172724']];const set=sets[Math.min(2,Math.floor(p*3))];st.style.background=set[0];st.style.color=set[1];const words=$$('.reveal-word',scene);words.forEach((el,i)=>{el.classList.toggle('filled',reduced||p*1.2>(i/words.length));el.style.setProperty('--word-color',set[1])})}if(scene.dataset.scene==='type'){const w=Math.round(400+p*400);$('.weight-word',scene).style.fontWeight=w;$('.live-weight',scene).textContent=w+' / '+(w<480?'Regular':w<600?'Medium':w<730?'Bold':'Extra bold')}if(scene.dataset.scene==='palette'){const w=innerWidth,mobile=w<650;$$('.fan-layer',scene).forEach((layer,i)=>{let x=(i-2)*(mobile?44:135)*p,y=(i-2)*(mobile?25:34)*(1-p),rot=(i-2)*(mobile?5:9)*p;layer.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px)) rotate(${rot}deg)`})}if(scene.dataset.scene==='icons'){$$('.magnet-icons>span',scene).forEach((el,i)=>{const endX=(i%4-1.5)*(innerWidth<650?73:145),endY=(Math.floor(i/4)-.5)*(innerWidth<650?85:130);const startX=Math.sin(i*2.3)*innerWidth*.34,startY=Math.cos(i*2.3)*180;el.style.transform=`translate(calc(-50% + ${startX*(1-p)+endX*p}px),calc(-50% + ${startY*(1-p)+endY*p}px)) rotate(${(i%2?22:-19)*(1-p)}deg)`})}});}
function onScroll(){if(!ticking){ticking=true;requestAnimationFrame(updateScenes)}}addEventListener('scroll',onScroll,{passive:true});addEventListener('resize',onScroll);reducedQuery.addEventListener('change',updateReduced);updateScenes();
$$('[data-skin]',root).forEach(b=>b.onclick=()=>{const theater=b.closest('.color-play'),set=skinSets[+b.dataset.skin];theater.style.setProperty('--play-bg',set[1]);theater.style.setProperty('--play-fg',set[2]);theater.style.setProperty('--play-ink',set[3]);$$('[data-skin]',theater).forEach(btn=>{btn.classList.toggle('selected',btn===b);btn.setAttribute('aria-pressed',btn===b)});theater.classList.remove('recolor');void theater.offsetWidth;theater.classList.add('recolor')});
$$('.demo-create-skin').forEach(b=>b.onclick=()=>{b.textContent='Project created';toast('Illustrative product state: project created')});
let timing=180;$$('[data-timing]').forEach(b=>b.onclick=()=>{timing=+b.dataset.timing;$$('[data-timing]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});playComposition()});function playComposition(){const c=$('.replay-composition');c.style.setProperty('--replay-duration',timing+'ms');c.classList.remove('is-playing');void c.offsetWidth;c.classList.add('is-playing')};if($('#replay-composition'))$('#replay-composition').onclick=playComposition;
const voiceContent={start:['folder','A little space<br>for your next idea.','Create a project to get started.','Create project'],success:['check','Your brand kit<br>is ready.','Review the colors and type before sharing.','Review brand kit'],error:['close','We couldn’t save<br>your changes.','Your draft is still here. Try saving again.','Try again']};$$('[data-voice]').forEach(b=>b.onclick=()=>{const v=voiceContent[b.dataset.voice],area=$('.voice-message');$('.message-icon',area).innerHTML=icon(v[0]);$('h2',area).innerHTML=v[1];$('p',area).textContent=v[2];$('.voice-action',area).textContent=v[3];$$('[data-voice]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});area.classList.remove('message-enter');void area.offsetWidth;area.classList.add('message-enter')});
if($('#focus-example'))$('#focus-example').onclick=()=>{toast('A clear, visible focus state.');$('#focus-example').classList.toggle('show-focus')};
const home=$('.hero');let pointerHandler;if(home){pointerHandler=e=>{if(reducedQuery.matches||userReduced)return;const r=home.getBoundingClientRect();home.style.setProperty('--pointer-x',((e.clientX-r.left)/r.width-.5)*25+'px');home.style.setProperty('--pointer-y',((e.clientY-r.top)/Math.min(r.height,900)-.5)*20+'px')};home.addEventListener('pointermove',pointerHandler)}
disposeExperience=()=>{removeEventListener('scroll',onScroll);removeEventListener('resize',onScroll);reducedQuery.removeEventListener('change',updateReduced);if(home&&pointerHandler)home.removeEventListener('pointermove',pointerHandler)};
};
render();
